74	export const dynamic = "force-dynamic";
75	
76	/**
77	 * Pick the port forward that actually serves a game server's own port, not
78	 * just the first one on the record — a customer can add extra forwards
79	 * (RCON web UI, Dynmap, a Bedrock/Geyser port, ...) that must never be
80	 * mistaken for the game's real connect port. Falls back to the first forward
81	 * if none matches, so a server whose family isn't in GAME_PORT (or has no
82	 * exact-matching forward yet) still shows *something* rather than nothing.
83	 * Single shared helper so the provisioning-overlay connect string, the header
84	 * connect string, and the custom-domain DNS instructions can never drift from
85	 * each other the way three independent inline copies previously could.
86	 *
87	 * Keys on `joinPortFor`, NOT `GAME_PORT`. `GAME_PORT` is the health-CHECK map
88	 * and for eight families (rust, ark, projectzomboid, factorio, arkasa, soulmask,
89	 * squad, kf2) it deliberately names an RCON/query/admin port instead of the join
90	 * port — see its comment in lib/games.ts. Reading it here meant a Rust customer
91	 * was shown their RCON port, 28016, as the address to give their players. Found
92	 * live 2026-09-06 on a real fresh provision. The RCON forward still exists (the
93	 * provisioning health check runs through it), so this must select the join port
94	 * explicitly rather than rely on there being only one game forward.
95	 */
96	function gameForwardFor(server: {
97	  portForwards: { guestPort: number; publicPort: number }[];
98	  osTemplate: { family?: string | null };
99	  gamePlan?: { gameFamily?: string | null } | null;
100	}): { guestPort: number; publicPort: number } | undefined {
101	  const family = (server.gamePlan?.gameFamily ?? server.osTemplate.family) as GameFamily | undefined;
102	  const joinPort = family && GAME_PORT[family] ? joinPortFor(family).port : undefined;
103	  const checkPort = family ? GAME_PORT[family]?.port : undefined;
104	  return (
105	    server.portForwards.find((f) => f.guestPort === joinPort) ??
106	    // The join forward can be legitimately absent on a server provisioned before
107	    // it was ever allocated — fall back to the check port rather than showing
108	    // nothing, same spirit as the final fallback below.
109	    server.portForwards.find((f) => f.guestPort === checkPort) ??
110	    server.portForwards[0]
111	  );
112	}
113	
114	function fmtUptime(seconds: number): string {
115	  if (!seconds || seconds <= 0) return "—";
116	  const d = Math.floor(seconds / 86400);
117	  const h = Math.floor((seconds % 86400) / 3600);
118	  const m = Math.floor((seconds % 3600) / 60);
119	  return d > 0 ? `${d}d ${h}h ${m}m` : h > 0 ? `${h}h ${m}m` : `${m}m`;
120	}
121	
122	type LiveStats = {
123	  cpu?: number;
124	  mem?: number;
125	  maxmem?: number;
126	  uptime?: number;
127	  netin?: number;
128	  netout?: number;
129	} | null;
130	
131	export default async function ServerPage({
132	  params,
133	  searchParams,
134	}: {
135	  params: Promise<{ id: string }>;
136	  searchParams: Promise<{ tab?: string; purchase?: string }>;
137	}) {
138	  const [{ id }, { tab, purchase }] = await Promise.all([params, searchParams]);
139	  const user = await requireUser();
140	  const server = await db.server.findUnique({
141	    where: { id },
142	    include: {
143	      plan: true,
144	      osTemplate: true,
145	      project: true,
146	      portForwards: { orderBy: { publicPort: "asc" } },
147	      firewallRules: { orderBy: [{ position: "asc" }, { createdAt: "asc" }] },
148	      jobs: { orderBy: { createdAt: "desc" }, take: 20 },
149	      dedicatedIp: true,
150	      node: true,
151	      // Needed to price a renewal correctly: a game server bills its game plan's
152	      // flat price, not the base VPS plan's term price.
153	      gamePlan: true,
154	    },
155	  });
156	  if (!server || (server.userId !== user.id && user.role !== "ADMIN")) notFound();
157	
158	  // Root password may be stored encrypted-at-rest (rootPasswordEnc); resolve the
159	  // display value through the decrypt fallback (legacy plaintext rows still work).
160	  const rootPassword = serverRootPassword(server);
161	
162	  const [projects, activePlans, osTemplates, extraDiskPriceCents, backupPlusCents, annualPct, ipMonthlyCentsLive] =
163	    await Promise.all([
164	      db.project.findMany({ where: { userId: server.userId }, orderBy: { name: "asc" } }),
165	      db.plan.findMany({ where: { active: true }, orderBy: { sortOrder: "asc" } }),
166	      db.osTemplate.findMany({
167	        where: { active: true, category: "PLAIN_OS" },
168	        orderBy: [{ sortOrder: "asc" }, { name: "asc" }],
169	      }),
170	      extraDiskPerGbCents(),
171	      backupPlusMonthlyCents(),
172	      // Live annual discount — feeds the "Renew now" quote below AND the resize
173	      // pickers, so an annual server's renewal/upgrade/downgrade all price against the
174	      // same rate it was sold at.
175	      annualDiscountPct(),
176	      // Fetched unconditionally now (not just `server.dedicatedIp ? … : 0`): the
177	      // "Add dedicated IP" card needs the live price to show a customer who does
178	      // NOT yet have one, same as extraDiskPriceCents above is fetched regardless
179	      // of whether this server currently holds any extra disk.
180	      dedicatedIpMonthlyCents(),
181	    ]);
182	
183	  // Retention offer: may this account still be shown "stay and save 50%" if it
184	  // attempts to cancel THIS server? Resolved once, server-side, and threaded
185	  // into CancelService rather than trusted client-side — see that function's
186	  // own doc comment (lib/actions-server-lifecycle.ts) for the full eligibility
187	  // rule. Skipped entirely for a free/already-deleting server, matching the
188	  // exact condition CancelService itself is only rendered under below.
189	  const cancellable = !server.isFree && server.status !== "DELETING";
190	  const retentionEligible = cancellable ? await checkRetentionOfferEligible(server.id) : false;
191	
192	  // VAT/GST for the SERVER OWNER (Finding 1), resolved from their billing country.
193	  const owner =
194	    server.userId === user.id ? user : (await db.user.findUnique({ where: { id: server.userId } })) ?? user;
195	  const renewTaxCtx = await taxContextForUser(owner);
196	
197	  // What "Renew now" will actually charge, priced through the SAME function the
198	  // action charges through, so the button cannot quote one figure and take
199	  // another. See lib/renewal-quote.ts for the incident.
200	  const renewQuote = renewalQuote(
201	    {
202	      termMonths: server.termMonths,
203	      extraDiskGB: server.extraDiskGB,
204	      plan: { name: server.plan.name, priceCents: server.plan.priceCents },
205	      // A game server is sold at its game plan's flat price, NOT the base VPS
206	      // plan it happens to be built on. Omitting this quoted an $8.99 renewal for
207	      // a $4.99 product.
208	      gamePlan: server.gamePlan
209	        ? { name: server.gamePlan.name, priceCents: server.gamePlan.priceCents, termMonths: server.gamePlan.termMonths }
210	        : null,
211	      dedicatedIp: server.dedicatedIp,
212	      wantsDedicatedIp: server.wantsDedicatedIp,
213	      backupTier: server.backupTier,
214	      grandfatheredRenewalCents: server.grandfatheredRenewalCents,
215	    },
216	    {
217	      ipMonthlyCents: server.dedicatedIp ? ipMonthlyCentsLive : 0,
218	      extraDiskPerGbCents: extraDiskPriceCents,
219	      backupPlusCents,
220	      annualDiscountPct: annualPct,
221	      // VAT/GST for the owner (Finding 1): the "Renews at $X" figure and the Renew
222	      // now quote are tax-inclusive, matching what renewNow charges.
223	      taxRatePercent: renewTaxCtx.ratePercent,
224	    },
225	  );
226	
227	  // The server's REAL disk: plan allowance + any separately-purchased extra disk.
228	  // Every disk figure on this page uses this, never `plan.diskGB` on its own.
229	  //
230	  // FIXED 2026-09-09: for a game server, "plan allowance" means the GAME
231	  // plan's disk, not the base VPS plan's — worker/index.ts's `provision()`
232	  // has used `server.gamePlan?.diskGB ?? server.plan.diskGB` since the
233	  // 2026-09-06 over-provisioning fix (a game plan is never LARGER than its
234	  // base VPS tier), but this page's own `totalDiskGB` was never updated to
235	  // match, so a game server's dashboard silently showed the bigger base-VPS
236	  // number here even though the VM itself was correctly provisioned at the
237	  // smaller, advertised size. Found live on a real Valheim server (30GB
238	  // advertised + actually provisioned, dashboard showed 50GB) — the exact
239	  // "advertised != displayed" trust problem the original fix existed to
240	  // prevent, just relocated to the display layer instead of provisioning.
241	  const baseDiskGB = server.gamePlan?.diskGB ?? server.plan.diskGB;
242	  const totalDiskGB = effectiveDiskGB(baseDiskGB, server.extraDiskGB);
243	
244	  const publicIp = server.node?.publicIp ?? process.env.PUBLIC_IP ?? "";
245	  const transitional = ["PENDING", "PROVISIONING", "REINSTALLING", "DELETING"].includes(server.status);
246	  const busy =
247	    transitional || server.jobs.some((j) => j.status === "QUEUED" || j.status === "RUNNING");
248	  const steady = ["RUNNING", "STOPPED"].includes(server.status);
249	
250	  let live: LiveStats = null;
251	  let snapshots: { name: string; snaptime?: number; description?: string }[] = [];
252	  let backups: { volid: string; ctime?: number; size?: number }[] = [];
253	  let pveUnavailable = false;
254	
255	  if (server.vmid && steady) {
256	    // Read through THIS server's own node's Proxmox client — vmids can
257	    // collide across nodes, so the bare vmStatus/listSnapshots/listBackups
258	    // (always the primary node) would show a customer someone else's VM's
259	    // stats the moment their server lives on a different node. Falls back to
260	    // the primary-node singleton only for the legacy case of a server with
261	    // no `node` relation at all (pre-multi-node rows).
262	    const conn = server.node ? pveForNode(server.node) : null;
263	    // listBackupsOn's own default storage id ("backup") is the PRIMARY's own
264	    // vzdump storage name — a non-primary node's is its own `storageHdd`
265	    // (worker/index.ts and lib/actions-server-ops.ts already resolve it this
266	    // way). Omitting this here made every node-2+ server's Backups tab fail
267	    // with "hypervisor is briefly unavailable" — confirmed live 2026-09-08,
268	    // Proxmox 500s on GET /nodes/<node>/storage/backup/content because that
269	    // storage id doesn't exist there (node-2's is "vmdata-hdd").
270	    const backupStorage = server.node
271	      ? server.node.isPrimary
272	        ? "backup"
273	        : (server.node.storageHdd ?? "backup")
274	      : "backup";
275	    const results = await Promise.allSettled([
276	      conn ? conn.vmStatus(server.vmid) : vmStatus(server.vmid),
277	      conn ? listSnapshotsOn(conn, server.vmid) : listSnapshots(server.vmid),
278	      conn ? listBackupsOn(conn, server.vmid, backupStorage) : listBackups(server.vmid),
279	    ]);
280	    if (results[0].status === "fulfilled") live = results[0].value as LiveStats;
281	    if (results[1].status === "fulfilled") snapshots = results[1].value as typeof snapshots;
282	    if (results[2].status === "fulfilled") backups = results[2].value as typeof backups;
283	    pveUnavailable = results.some((r) => r.status === "rejected");
284	  }
285	
286	  // Dedicated-IP servers connect straight to their own public IP on port 22; NAT
287	  // servers use the platform public IP + the forwarded SSH port. (A dedicated
288	  // server has sshPort=null, which previously fell through to "provisioning…".)
289	  const sshCommand = server.dedicatedIp
290	    ? `ssh root@${server.dedicatedIp.address}`
291	    : server.sshPort
292	      ? `ssh root@${publicIp} -p ${server.sshPort}`
293	      : null;
294	
295	  // Single-item terminal list for this server — connect string computed the
296	  // same way as the Claude Code hub (dedicated IP → own IP, else NAT SSH port).
297	
298	  // SFTP/SSH connection details: dedicated-IP servers connect to their own IP on
299	  // port 22; NAT servers use the platform public IP + the forwarded SSH port.
300	  const dedicated = !!server.dedicatedIp;
301	  const sftpHost = dedicated ? server.dedicatedIp!.address : publicIp || null;
302	  const sftpPort = dedicated ? 22 : server.sshPort;
303	  /* A game server is one that was SOLD as a game server — `gamePlanId` — and
304	     its family is the game plan's, falling back to the OS template's.
305	     This used to test `osTemplate.family` alone, which is wrong whenever a game
306	     is installed on top of a plain OS image: `mc-survival` carries
307	     gamePlan.gameFamily="minecraft" on osTemplate.family="ubuntu", so it failed
308	     the test and rendered the VPS panel — no game console, no players, no mods,
309	     no game settings, for a Minecraft server. lib/game-config.ts's `familyFor`
310	     has always used this precedence; the page now matches it. */
311	  const isGameServer =
312	    server.gamePlanId !== null || GAME_FAMILIES.includes(server.osTemplate.family as GameFamily);
313	
314	  // Post-payment "setting up / it's live" interstitial. Connect string mirrors
315	  // the game-branch's own `connect` computation below via the shared
316	  // gameForwardFor() helper, so the two can never drift from each other.
317	  const overlayForward = isGameServer ? gameForwardFor(server) : undefined;
318	  const overlayConnect = isGameServer
319	    ? server.dedicatedIp
320	      ? `${server.dedicatedIp.address}${overlayForward ? `:${overlayForward.guestPort}` : ""}`
321	      : overlayForward
322	        ? `${publicIp}:${overlayForward.publicPort}`
323	        : publicIp || null
324	    : sshCommand;
325	  // Real (not cosmetic) step label when the worker has recorded one for this
326	  // server's CURRENT provisioning run — see lib/provisioning-step.ts. Null while
327	  // transitional but no checkpoint reached yet (or in SANDBOX, which completes
328	  // before any step is ever written) simply falls back to the overlay's existing
329	  // cosmetic cycling text.
330	  const liveStep = transitional ? await serverProvisioningStep(server.id) : null;
331	  /* The Nexion provisioning screen. It replaces <ProvisioningOverlay/> for the
332	     three states it covers — building, live, failed — and is driven by the SAME
333	     real signals the old one used: `server.status` and `serverProvisioningStep`.
334	     The design sandbox animated this on a timer; nothing here advances unless
335	     the worker actually reported a step.
336	
337	     This is the destination `payAndDeploy` redirects to, so it is the screen a
338	     customer really sees after ordering — the wizard's own step 5 is never
339	     reached on that path. */
340	  const overlay = transitional || purchase === "1" || server.status === "ERROR" ? (
341	    <Provisioning
342	      phase={server.status === "ERROR" ? "error" : transitional ? "working" : "ready"}
343	      liveStep={liveStep}
344	      /* Sandbox only: no hypervisor here means the worker never reports a step,
345	         so the stage list would sit inert forever and the screen could not be
346	         judged. Never true in production — NXEON_SANDBOX is not set there. */
347	      simulate={process.env.NXEON_SANDBOX === "1" && !liveStep}
348	      hostname={server.hostname}
349	      planName={isGameServer ? server.gamePlan?.name ?? server.plan.name : server.plan.name}
350	      osName={server.osTemplate.name}
351	      connectAddress={overlayConnect}
352	      error={server.provisionError}
353	      dashboardHref={`/dashboard/servers/${server.id}`}
354	      service={isGameServer ? "game" : "vps"}
355	      /* Real figures off the plan the customer is actually being given — the
356	         same `totalDiskGB` the rest of the page uses, so the provisioning
357	         screen and the server page cannot quote different disk. */
358	      specs={[
359	        { icon: "cpu", text: `${server.plan.cpuCores} vCPU` },
360	        { icon: "ram", text: `${server.plan.ramMB / 1024} GB RAM` },
361	        { icon: "database", text: `${totalDiskGB} GB NVMe` },
362	      ]}
363	      slots={isGameServer ? server.gamePlan?.slots ?? null : null}
364	      /* `Node.region` is a slug ("sgp1"); REGION_LABELS is the one place that
365	         turns it into the name a customer recognises. */
366	      regionName={server.node ? REGION_LABELS[server.node.region] ?? null : null}
367	    />
368	  ) : null;
369	
370	  /* While the server is being built — or immediately after paying — this screen
371	     is the WHOLE page. The tabs, the access panel and the SSH box below are
372	     controls for a machine that does not exist yet: showing "provisioning…"
373	     inside a Root password field invites the customer to keep checking a box
374	     that cannot fill. They come back the moment the server is real, via the
375	     Continue button. */
376	  if (overlay) {
377	    return (
378	      <div className="min-h-[70vh]">
379	        {transitional && <AutoRefresh />}
380	        {overlay}
381	      </div>
382	    );
383	  }
384	
385	
386	  // Per-game customization (only for game servers with a customization schema).
387	  const gameFamily = familyFor(server);
388	  const gameSchema = schemaFor(gameFamily);
389	  const gameVariant =
390	    gameSchema && server.gameVariant && isValidVariant(gameFamily!, server.gameVariant)
391	      ? server.gameVariant
392	      : gameSchema?.defaultVariant ?? "";
393	  const gameValidated = gameFamily
394	    ? validateConfig(gameFamily, (server.gameConfig as Record<string, unknown> | null) ?? {})
395	    : null;
396	  const gameValues = gameValidated && gameValidated.ok ? gameValidated.values : {};
397	
398	  /* ---------- Tab: Overview ---------- */
399	  /* ---------- The panel's identity + vitals snapshot ----------
400	     Assembled once and handed to the shell. The address comes from
401	     lib/nx/connect-address.ts rather than being worked out again — this page
402	     had re-derived the same answer inline in four separate places. */
403	  const vpsUptime = await uptimeFor([server.id]);
404	
405	  const vpsHeader: VpsHeaderData = {
406	    serverId: server.id,
407	    name: server.label || server.name,
408	    hostname: server.hostname,
409	    status: server.status,
410	    planName: server.plan.name,
411	    osName: server.osTemplate.name,
412	    osFamily: server.osTemplate.family,
413	    isFree: server.isFree,
414	    renewLabel: server.isFree
415	      ? null
416	      : `${fmtMoney(renewQuote.totalCents)} / ${renewQuote.durationLabel}`,
417	    specs: {
418	      vcpu: server.plan.cpuCores,
419	      ramMB: server.plan.ramMB,
420	      diskGB: totalDiskGB,
421	      extraDiskGB: server.extraDiskGB,
422	    },
423	    connect: {
424	      address: server.dedicatedIp?.address ?? server.node?.publicIp ?? null,
425	      sshCommand,
426	      ipv6: server.ipv6 ?? null,
427	    },
428	    location: {
429	      label: server.node ? regionLabel(server.node.region) : null,
430	      country: server.node ? REGION_COUNTRY[server.node.region] ?? null : null,
431	    },
432	    live: live
433	      ? {
434	          cpuPct: (live.cpu ?? 0) * 100,
435	          memBytes: live.mem ?? 0,
436	          maxMemBytes: live.maxmem ?? 0,
437	          uptimeSec: live.uptime ?? 0,
438	        }
439	      : null,
440	    /* Read inside the guest, client-side — see the note in VpsHero. */
