38	type TabKey =
39	  | "overview" | "console" | "files" | "mods" | "backups"
40	  | "players" | "schedules" | "build" | "settings" | "activity";
41	
42	const TABS: { key: TabKey; label: string; icon: string; badge?: string }[] = [
