15	 * Now each of those belongs to a named section reachable from a rail, in the
16	 * order of how often they are wanted, with the destructive ones fenced off at
17	 * the end in red. The sections are slots: the page composes what goes in them,
18	 * so nothing that worked before is lost.
19	 */
20	
21	export type SettingsSectionKey =
22	  | "upgrade" | "server" | "game" | "network" | "access" | "danger";
23	
24	export type SettingsSlots = Partial<Record<SettingsSectionKey, ReactNode>>;
25	
26	const SECTIONS: { key: SettingsSectionKey; label: string; sub: string; icon: string; tone?: "danger" }[] = [
27	  { key: "upgrade", label: "Resources",    sub: "Plan, slots and storage",   icon: "bolt" },
28	  { key: "server",  label: "Server",       sub: "Name, updates, behaviour",  icon: "gear" },
29	  { key: "game",    label: "Game settings",sub: "This game's own options",   icon: "gamepad" },
30	  { key: "network", label: "Network",      sub: "Connect address and domain",icon: "globe" },
31	  { key: "access",  label: "Server access",sub: "SSH, SFTP and credentials", icon: "key" },
32	  { key: "danger",  label: "Danger Zone",  sub: "Reinstall, wipe or cancel", icon: "warntriangle", tone: "danger" },
33	];
34	
35	export function GameSettingsShell({ slots, gameLabel }: { slots: SettingsSlots; gameLabel: string }) {
36	  const shown = SECTIONS.filter((s) => slots[s.key]);
37	  const [sec, setSec] = useState<SettingsSectionKey>(shown[0]?.key ?? "server");
38	  const active = shown.find((s) => s.key === sec) ?? shown[0];
39	
40	  if (!active) return null;
41	
42	  return (
43	    <div className="grid gap-4 lg:grid-cols-[252px_minmax(0,1fr)]">
44	      <nav className="flex h-fit flex-col gap-1 rounded-[16px] border border-rim-hi bg-[rgba(6,14,36,.72)] p-2">
45	        {shown.map((s) => {
46	          const on = sec === s.key;
47	          const danger = s.tone === "danger";
48	          return (
49	            <button
50	              key={s.key}
51	              type="button"
52	              onClick={() => setSec(s.key)}
53	              aria-current={on ? "true" : undefined}
54	              className={
55	                "flex items-center gap-3 rounded-[11px] border px-3 py-2.5 text-left transition " +
56	                (on
57	                  ? danger
58	                    ? "border-red-500/45 bg-red-500/12"
59	                    : "border-[#8b5cff]/70 bg-[linear-gradient(120deg,rgba(80,40,190,.42),rgba(30,40,120,.3))]"
60	                  : "border-transparent hover:bg-white/[0.04]")
61	              }
62	            >
63	              <Icon
64	                name={s.icon}
65	                size={16}
66	                tone="inherit"
67	                className={"flex-none " + (danger ? "text-red-400" : on ? "text-white" : "text-tx-dim")}
68	              />
69	              <span className="flex min-w-0 flex-col">
70	                <span className={"truncate text-[13px] font-bold " + (danger ? "text-red-300" : on ? "text-white" : "text-tx-dim")}>
71	                  {s.key === "game" ? `${gameLabel} settings` : s.label}
72	                </span>
73	                <span className="truncate text-[11px] text-tx-faint">{s.sub}</span>
74	              </span>
75	            </button>
76	          );
77	        })}
78	      </nav>
79	
80	      {/* The slotted sections keep their own cards; this only groups them. */}
81	      <div className="flex min-w-0 flex-col gap-4 [&_.card]:rounded-[16px]">
82	        {slots[active.key]}
83	      </div>
84	    </div>
85	  );
86	}
