3	import { useState, useTransition } from "react";
4	import { cancelService } from "@/lib/actions-server-lifecycle";
5	import { RetentionOfferModal } from "./RetentionOfferModal";
6	
7	/**
8	 * Danger-zone control for self-serve cancellation (Finding 2). Offers the two
9	 * server-side modes — cancel at period end (stop auto-renew, keep to expiry) and
10	 * immediate termination (destroy now, prorated refund to wallet) — behind an explicit
11	 * confirm that states the data-retention consequence and the refund figure.
12	 *
13	 * `retentionOfferEligible` (resolved server-side by the page — see
14	 * lib/actions-server-lifecycle.ts's function of the same name, never trust a
15	 * client-only version of this for something that decides whether a real
16	 * discount can be claimed) gates a "Wait — before you go" interstitial ahead
17	 * of EITHER cancel path: accepting it claims 50% off the next renewal and
18	 * keeps the server running; declining runs the exact cancellation the
19	 * customer originally clicked, unchanged.
20	 */
21	export function CancelService({
22	  serverId,
23	  hostname,
24	  expiresAt,
25	  autoRenew,
26	  refundEstimateCents,
27	  retentionOfferEligible,
28	}: {
29	  serverId: string;
30	  hostname: string;
31	  /** ISO date; null for a free/no-term server (period-end is not offered then). */
32	  expiresAt: string | null;
33	  autoRenew: boolean;
34	  /** Prorated refund the customer would get on IMMEDIATE termination, in cents. */
35	  refundEstimateCents: number;
36	  /** Server-resolved: may this account still be offered the one-time "stay and save" discount? */
37	  retentionOfferEligible: boolean;
38	}) {
39	  const [open, setOpen] = useState(false);
40	  const [pending, startTransition] = useTransition();
41	  const [error, setError] = useState<string | null>(null);
42	  const [done, setDone] = useState<string | null>(null);
43	  // Which cancel mode the retention interstitial is standing in front of —
44	  // null means the interstitial is not showing.
45	  const [pendingCancelMode, setPendingCancelMode] = useState<"immediate" | "period_end" | null>(null);
46	
47	  const money = (c: number) => `$${(c / 100).toFixed(2)}`;
48	  const expiryLabel = expiresAt ? new Date(expiresAt).toISOString().slice(0, 10) : null;
49	
50	  const runCancel = (mode: "immediate" | "period_end") => {
51	    setError(null);
52	    setDone(null);
53	    startTransition(async () => {
54	      const res = await cancelService(serverId, mode);
55	      if (res?.error) setError(res.error);
56	      else if (res?.message) {
57	        setDone(res.message);
58	        setOpen(false);
59	      }
60	    });
61	  };
62	
63	  const run = (mode: "immediate" | "period_end") => {
64	    if (mode === "immediate") {
65	      const msg =
66	        `Immediately terminate ${hostname}? This destroys the server and PERMANENTLY erases all its data — this cannot be undone.` +
67	        (refundEstimateCents > 0
68	          ? `\n\n${money(refundEstimateCents)} for the unused part of your term will be credited to your wallet.`
69	          : "\n\nNo refund applies (nothing left on the paid term).");
70	      if (!window.confirm(msg)) return;
71	    }
72	    // Offer the retention discount FIRST, before the cancellation itself runs
73	    // — the customer still gets the exact same confirm/refund-figure step
74	    // above if they decline it. Never re-shown once the account has used it
75	    // (retentionOfferEligible is resolved server-side per render).
76	    if (retentionOfferEligible) {
77	      setPendingCancelMode(mode);
78	      return;
79	    }
80	    runCancel(mode);
81	  };
82	
83	  if (done) {
84	    return (
85	      <div className="rounded-lg border border-emerald-500/30 bg-emerald-500/[0.06] px-3 py-2.5 text-xs text-emerald-200">
86	        {done}
87	      </div>
88	    );
89	  }
90	
91	  return (
92	    <div className="rounded-lg border border-red-500/20 bg-red-500/[0.03] p-4">
93	      <div className="flex flex-wrap items-center justify-between gap-3">
94	        <div>
95	          <p className="text-sm font-semibold text-red-200">Cancel this service</p>
96	          <p className="mt-0.5 text-xs text-slate-400">
97	            Stop auto-renew and keep it to expiry, or terminate now.
98	          </p>
