  const isImpersonating = (await impersonating()) !== null;

  const renewables = [
    ...servers.map((s) => ({ name: s.hostname, kind: "Server", at: s.expiresAt, auto: s.autoRenew })),
    ...hosting.map((h) => ({ name: h.primaryDomain, kind: "Hosting", at: h.expiresAt, auto: true })),
    ...domains.map((d) => ({ name: d.name, kind: "Domain", at: d.expiresAt, auto: true })),
