  renewables.sort((a, b) => a.at.getTime() - b.at.getTime());
  const next = renewables[0] ?? null;
  const daysUntilNext = next ? Math.max(0, Math.round((next.at.getTime() - now.getTime()) / 86_400_000)) : null;

  // Same meter the worker sweeps and the same "measured" gate the original
  // dashboard's Usage panel uses — a server this has never metered reports
  // that honestly instead of a fabricated 0%.
  const cards = await listPaymentCards(user.id);

  const bwHealth = await readBwMeterHealth();
  const bandwidth = bwServers.map((s) => {
    const view = bwUsageView(s, (s.plan?.bandwidthTB ?? 0) * 1e12, bwHealth);
    return {
      hostname: s.hostname,
      measured: view.measured,
      usedBytes: view.usedBytes,
      allowanceBytes: view.allowanceBytes,
      pct: view.pct,
      partial: view.partial,
    };
