3	import { useCallback, useEffect, useState, useTransition } from "react";
4	import { getGameWorlds, sendGameCommand } from "@/lib/actions-game-control";
5	
6	type WorldEntry = { name: string; sizeBytes: number; isDir: boolean };
7	
8	function fmt(bytes: number): string {
9	  if (bytes < 1024) return `${bytes} B`;
10	  if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`;
11	  if (bytes < 1024 * 1024 * 1024) return `${(bytes / (1024 * 1024)).toFixed(1)} MB`;
12	  return `${(bytes / (1024 * 1024 * 1024)).toFixed(2)} GB`;
13	}
14	
15	export function GameWorlds({ serverId, running }: { serverId: string; running: boolean }) {
16	  const [entries, setEntries] = useState<WorldEntry[] | null>(null);
17	  const [dir, setDir] = useState<string | null>(null);
18	  const [err, setErr] = useState<string | null>(null);
19	  const [msg, setMsg] = useState<string | null>(null);
20	  const [pending, start] = useTransition();
21	
22	  const refresh = useCallback(() => {
23	    start(async () => {
24	      const r = await getGameWorlds(serverId);
25	      if (r.ok) { setEntries(r.entries); setDir(r.dir); setErr(null); }
26	      else setErr(r.error);
27	    });
28	  }, [serverId]);
29	
30	  useEffect(() => { if (running) refresh(); }, [running, refresh]);
31	
32	  const worlds = entries?.filter((e) => e.isDir && /^world/.test(e.name)) ?? [];
33	  const totalSize = worlds.reduce((s, e) => s + e.sizeBytes, 0);
34	
35	  function saveAll() {
36	    setMsg(null);
37	    start(async () => {
38	      const r = await sendGameCommand(serverId, "save-all");
39	      if (r.ok) setMsg("World saved successfully.");
40	      else setErr(r.error);
41	    });
42	  }
43	
44	  return (
45	    <div className="card">
46	      <div className="flex items-center justify-between">
47	        <div>
48	          <h3 className="font-semibold">Worlds</h3>
49	          <p className="mt-0.5 text-sm text-slate-400">
50	            {dir ? `Located at ${dir}` : "Your server's world directories."}
51	          </p>
52	        </div>
53	        <div className="flex gap-2">
54	          <button className="btn-ghost text-xs" onClick={saveAll} disabled={pending || !running}>
55	            {pending ? "Saving…" : "Save all"}
56	          </button>
57	          <button className="text-xs text-slate-400 hover:text-white disabled:opacity-40" onClick={refresh} disabled={pending || !running}>
58	            Refresh
59	          </button>
60	        </div>
61	      </div>
62	
63	      {err && <p className="mt-3 text-sm text-amber-300">{err}</p>}
64	      {msg && <p className="mt-2 text-sm text-emerald-400">{msg}</p>}
65	
66	      {!running ? (
67	        <p className="mt-4 text-sm text-slate-500">Start the server to view worlds.</p>
68	      ) : entries === null ? (
69	        <p className="mt-4 text-sm text-slate-500">Loading…</p>
70	      ) : worlds.length === 0 ? (
71	        <p className="mt-4 text-sm text-slate-500">No world directories found.</p>
72	      ) : (
73	        <>
74	          <ul className="mt-4 divide-y divide-white/[0.06]">
75	            {worlds.map((w) => (
76	              <li key={w.name} className="flex items-center justify-between py-3">
77	                <span className="flex items-center gap-3">
78	                  <span className="flex h-10 w-10 items-center justify-center rounded-xl bg-emerald-500/10 text-lg">
79	                    {w.name.includes("nether") ? "🔥" : w.name.includes("end") ? "🌌" : "🌍"}
80	                  </span>
81	                  <span>
82	                    <p className="text-sm font-medium text-slate-100">{w.name}</p>
83	                    <p className="text-xs text-slate-500">{fmt(w.sizeBytes)}</p>
84	                  </span>
85	                </span>
86	              </li>
87	            ))}
88	          </ul>
89	          <div className="mt-3 border-t border-white/[0.06] pt-3">
90	            <p className="text-xs text-slate-500">Total world size: {fmt(totalSize)}</p>
91	          </div>
92	        </>
93	      )}
94	    </div>
95	  );
96	}
