8	/**
9	 * Backups, in the two kinds this platform actually makes.
10	 *
11	 * SERVER IMAGES are Proxmox vzdump archives of the whole VM, on separate
12	 * storage, scheduled by the worker and restorable in place. That is what the
13	 * old tab showed — as a three-column table with no restore, no download and no
14	 * per-row action, even though the restore action and a guarded download route
15	 * both exist.
16	 *
17	 * WORLD ARCHIVES are per-game `.tar.gz` saves. `createGameBackup`,
18	 * `getGameBackups` and the `GAME_BACKUP` worker job have been real for a long
19	 * time and NOTHING in the panel called them: the only consumer was
20	 * components/customer/game/GameManage.tsx, which stopped being reachable when
21	 * the game panel was rewritten. Its own completion notification still links to
22	 * `?tab=manage`, a tab that no longer exists. They have a home now.
23	 *
24	 * Nothing here invents a storage quota. The concept shows "18.6 GB / 100 GB";
25	 * archive sizes are real and summable, a quota is not a number this platform
26	 * holds, so the total used is shown and the ceiling is not.
27	 */
28	
29	export type ImageBackup = { volid: string; size: number | null; ctime: number | null };
30	
31	function whenLabel(ms: number): string {
32	  return new Date(ms).toLocaleString("en-US", {
33	    year: "numeric", month: "short", day: "numeric", hour: "2-digit", minute: "2-digit",
34	  });
35	}
36	
37	function Card({ title, sub, action, children }: {
38	  title: string; sub?: string; action?: ReactNode; children: ReactNode;
39	}) {
40	  return (
41	    <section className="flex min-w-0 flex-col rounded-[16px] border border-rim-hi bg-[linear-gradient(180deg,rgba(10,22,48,.5),rgba(2,7,20,.62))]">
42	      <div className="flex flex-wrap items-start gap-3 border-b border-rim-soft px-4 py-3">
43	        <div className="min-w-0 flex-1">
44	          <h3 className="text-[14px] font-extrabold text-white">{title}</h3>
45	          {sub && <p className="mt-0.5 text-[12px] text-tx-dim">{sub}</p>}
46	        </div>
47	        {action}
48	      </div>
49	      <div className="min-w-0 flex-1 p-4">{children}</div>
50	    </section>
