130	      </div>
131	
132	      <div className="flex w-fit gap-1 rounded-[11px] border border-rim-hi bg-[rgba(6,14,36,.72)] p-1">
133	        {([["images", `Server images (${images.length})`], ["worlds", "World archives"]] as const).map(([k, label]) => (
134	          <button key={k} type="button" onClick={() => setView(k)} aria-pressed={view === k}
