143	        <div className="grid gap-4 xl:grid-cols-[minmax(0,1.7fr)_minmax(0,1fr)]">
144	          <Card
145	            title="Server images"
146	            sub={`Full-machine copies on separate storage. The oldest is pruned once there are more than ${keepCount}.`}
