184	            {schedulePanel}
185	            {restorePanel}
186	          </div>
187	        </div>
188	      ) : (
189	        <div className="grid gap-4 xl:grid-cols-[minmax(0,1.7fr)_minmax(0,1fr)]">
190	          <Card
191	            title="World archives"
192	            sub={`Just the ${gameLabel} save directory, as a .tar.gz you can download.`}
