248	              </p>
249	            </Card>
250	
251	            <Card title="Storage">
252	              <dl className="flex flex-col gap-2.5">
253	                <div className="flex items-center justify-between gap-3">
254	                  <dt className="text-[12.5px] text-tx-dim">Server images</dt>
255	                  <dd className="text-[12.5px] font-semibold text-white">{fmtBytes(imagesUsed)}</dd>
256	                </div>
257	                <div className="flex items-center justify-between gap-3">
