69	      userId: true,
70	      status: true,
71	      hostname: true,
72	      label: true,
73	      rootPassword: true,
74	      rootPasswordEnc: true,
75	      sshPort: true,
76	      gameConfig: true,
77	      dedicatedIp: { select: { address: true } },
78	      node: { select: { publicIp: true } },
79	      osTemplate: { select: { family: true } },
80	      gamePlan: { select: { gameFamily: true } },
81	    },
82	  });
