/** Charge the prorated difference and queue the tier change. */
export async function changeGameTier(
  serverId: string,
  gamePlanId: string,
): Promise<{ ok?: true; error?: string }> {
  // Same impersonation guard as every other money movement: an admin acting as
  // a customer must not be able to put a charge on that customer's balance.
  await assertNotImpersonating();
  const { user } = await ownedServer(serverId);

  const unverified = await emailVerificationError(user);
  if (unverified) return { error: unverified };

  try {
    const quote = await gameResizeQuote(serverId, gamePlanId);
    if (quote.prorateCents > user.balanceCents) {
      const short = ((quote.prorateCents - user.balanceCents) / 100).toFixed(2);
      return {
        error: `This costs $${(quote.prorateCents / 100).toFixed(2)} for the rest of your term — $${short} more than your balance. Add funds and try again.`,
      };
    }
    await applyGameResize({ serverId, gamePlanId, actorUserId: user.id });
  } catch (e) {
    if (e instanceof ResizeError) return { error: e.message };
    if (e instanceof InsufficientBalanceError) return { error: "Your balance changed — top up and try again." };
    throw e;
  }

  revalidatePath(`/dashboard/servers/${serverId}`);
  return { ok: true };
}
