"use client";
import { useState, useTransition } from "react";
import { useRouter } from "next/navigation";
import { toggleAutoUpdate, triggerGameUpdate } from "@/lib/actions-server-ops";
/**
 * Game-server auto-update controls: a toggle for `Server.autoUpdate` plus an
 * "Update now" button that enqueues a one-off GAME_UPDATE job.
 */
export function GameAutoUpdate({
  serverId,
  gameName,
  autoUpdate,
  canUpdate,
  busy,
}: {
  serverId: string;
  gameName: string;
  autoUpdate: boolean;
  /** true when the VM is RUNNING (required for the SSH update) */
  canUpdate: boolean;
  /** true when another job is in flight */
  busy: boolean;
}) {
  const router = useRouter();
  const [enabled, setEnabled] = useState(autoUpdate);
  const [error, setError] = useState<string | null>(null);
  const [savingToggle, startToggle] = useTransition();
  const [updating, startUpdate] = useTransition();
  function flip() {
    const next = !enabled;
    setEnabled(next); // optimistic
    startToggle(async () => {
      setError(null);
      const res = await toggleAutoUpdate(serverId, next);
      if (res?.error) {
        setEnabled(!next); // revert
        setError(res.error);
      }
    });
  }
  function updateNow() {
    startUpdate(async () => {
      setError(null);
      const res = await triggerGameUpdate(serverId);
      if (res?.error) setError(res.error);
      else router.refresh();
    });
  }
  return (
    <div className="card">
      <div className="flex flex-wrap items-start justify-between gap-4">
        <div>
          <h2 className="font-semibold">Game updates</h2>
          <p className="mt-1 max-w-md text-sm text-slate-400">
            Keep your {gameName} server current. Updates run the game&apos;s update command over SSH
            and restart the service — expect a short interruption while it applies.
          </p>
        </div>
        <button
          className="btn-primary"
          disabled={updating || busy || !canUpdate}
          onClick={updateNow}
          title={!canUpdate ? "Server must be running" : undefined}
        >
          {updating ? "Queueing…" : "Update now"}
        </button>
      </div>
      <div className="divider" />
      <label className="flex cursor-pointer items-center justify-between gap-4">
        <span className="text-sm">
          <span className="font-medium">Automatic updates</span>
          <span className="mt-0.5 block text-xs text-slate-500">
            When on, we periodically update this server to the latest version in the background.
          </span>
        </span>
        <button
          type="button"
          role="switch"
          aria-checked={enabled}
          disabled={savingToggle}
          onClick={flip}
          className={`relative inline-flex h-6 w-11 shrink-0 items-center rounded-full transition-colors ${
            enabled ? "bg-brand-500" : "bg-white/15"
          } ${savingToggle ? "opacity-60" : ""}`}
        >
          <span
            className={`inline-block h-5 w-5 transform rounded-full bg-[#fff] shadow transition-transform ${
              enabled ? "translate-x-5" : "translate-x-0.5"
            }`}
          />
        </button>
      </label>
      {error && <p className="mt-3 text-sm text-red-400">{error}</p>}
    </div>
  );
}

/**
 * Turn observed facts into the one thing the customer is told.
 *
 * Every refusal names the reason AND the command to run, because "update failed"
 * on a game server six hours after the fact is useless without a next step.
 * Every success states precisely what was proven — including, for minecraft and
 * terraria, that no game update took place at all, because there is no update
 * source for those families and saying otherwise was the original lie.
 */
export function judgeGameUpdate(opts: {
  family: GameFamily;
  hostname: string;
  facts: GameUpdateFacts;
}): GameUpdateVerdict {
  const { family, hostname, facts: f } = opts;
  const appId = STEAM_APPID[family];

  if (!f.complete) {
    return {
      ok: false,
      reason:
        `the update script did not run to completion on ${hostname} (no end marker), so nothing about ` +
        `this run can be verified — the connection may have dropped or the command timed out. ` +
        `Nothing is being claimed. Re-run it by hand: systemctl status <your ${family} unit>`,
    };
  }

  if (!f.unit) {
    return {
      ok: false,
      reason:
        `no systemd service for ${family} was found on ${hostname}, so nothing was updated and ` +
        `nothing was restarted. Check what the server actually runs with: ` +
        `systemctl list-units --type=service | grep -i ${family}`,
    };
  }

  if (appId && f.steam === "absent") {
    return {
      ok: false,
      reason:
        `steamcmd is not installed on ${hostname}, so the ${family} game files were NOT updated. ` +
        `Auto-update cannot work on this server until it is present: apt-get install -y steamcmd ` +
        `(or reinstall from the ${family} image).`,
    };
  }

  if (appId && f.steam !== "ok" && f.steam !== "current") {
    const detail = f.steamErrors.length ? ` steamcmd said: ${f.steamErrors.slice(0, 3).join(" | ")}` : "";
    return {
      ok: false,
      reason:
        `steamcmd did not report a successful update of app ${appId} on ${hostname} ` +
        `(exit ${f.steamRc ?? "unknown"}), so the game files were not updated and the service was ` +
        `left alone.${detail} Re-run by hand: steamcmd +login anonymous +app_update ${appId} validate +quit`,
    };
  }

  // Nothing was restarted on these paths, so the state we observed is simply the
  // state the server was already in — do not describe it as a restart outcome.
  const restarted = f.steam === "ok";

  if (f.state !== "active") {
    return {
      ok: false,
      reason: restarted
        ? `${f.unit} on ${hostname} is "${f.state}" after the restart` +
          (f.restartRc !== null && f.restartRc !== 0 ? ` (systemctl restart exited ${f.restartRc})` : "") +
          `, so your game server is NOT running. It was "${f.wasActive}" before this ran. ` +
          `Diagnose with: systemctl status ${f.unit} ; journalctl -u ${f.unit} -n 50`
        : `${f.unit} on ${hostname} is "${f.state}" — your game server is NOT running. Nothing was ` +
          `updated or restarted by this check, so this is not something we just did to it. ` +
          `Diagnose with: systemctl status ${f.unit} ; journalctl -u ${f.unit} -n 50`,
    };
  }

  if (f.steam === "ok") {
    return {
      ok: true,
      notify: true, // a new build really was downloaded and applied
      title: `${family} updated on ${hostname}`,
      body:
        `steamcmd downloaded a new build of app ${appId}, and ${f.unit} was restarted and is active again ` +
        `(verified with systemctl, not assumed from an exit code).`,
    };
  }

  if (f.steam === "current") {
    return {
      ok: true,
      notify: false, // nothing happened; four of these a day is noise, not news
      title: `${family} on ${hostname} is already up to date`,
      body:
        `steamcmd confirmed app ${appId} is already up to date, so nothing was downloaded and ${f.unit} was ` +
        `NOT restarted — no players were disconnected. It is active.`,
    };
  }

  // No update source exists for this family. Say that, rather than implying one —
  // and do not restart, which is all this job could otherwise do here.
  return {
    ok: true,
    notify: false,
    title: `${family} server checked on ${hostname}`,
    body:
      `${f.unit} is active (verified). ${family} has no automatic update source on Nxeon, so there was ` +
      `nothing to download and your server was NOT restarted — restarting it every few hours would ` +
      `disconnect your players to change nothing. Update the server files yourself when a new version ships.`,
  };
}

// Player-count → recommended resources, per game family. Pure/client-safe (no DB,
// no server-only imports) so the game deploy wizard's "how many players?" slider
// can compute a live recommendation with no round trip, the same way
// lib/custom-plan-pricing.ts prices the raw CPU/RAM/disk sliders.
//
// ─── DERIVATION ───────────────────────────────────────────────────────────────
// Every family already has 2-3 REAL, shipped tiers in the catalog (prisma/
// seed-gameplans.ts, seed-wave1-games.ts, seed-wave2-games.ts), each with actual
// ramMB/cpuCores/diskGB paired with a player-slot count. Rather than invent numbers
// from scratch, each family's curve below is a least-squares linear fit
// (resources = base + perPlayer × players) over that family's OWN seeded tiers —
// so within (and near) the range the catalog already sells, these numbers are
// GROUNDED in real, already-published specs, not guesses.
//
// Extrapolating the fitted line far PAST a family's largest seeded tier is where
// confidence drops — a straight line fit to 2-3 points at the low end is a rough
// estimate of what a much bigger population needs, not a measurement. That's
// exactly the case this slider exists for (a customer past the top of the normal
// tier ladder), so `maxSeededSlots` is recorded on every curve and
// `playerSliderMax` caps the slider at 5x it — generous enough to be useful for a
// genuinely large deployment, conservative enough that the recommendation is
// still a multiple-not-orders-of-magnitude extrapolation. See the design report
// for exactly which families' HIGH-player-count numbers are the least certain
// (the ones with only 2 seeded tiers, or a small `maxSeededSlots`) — the owner
// should sanity-check those before this ships, same as any new pricing surface.
//
// The recommendation is always a DEFAULT-SETTER, never a constraint: the caller
// (GameDeployWizard) applies it through clampCustomPlanSpec, so it can never
// itself produce a spec below the custom-plan floor (Max) or above the ceiling —
// the customer can still freely drag the underlying CPU/RAM/disk sliders above or
// below whatever this suggests.
