import { GAME_PORT, joinPortFor, joinPortsFor, GAME_FAMILIES } from "./lib/games.mts";
import { readFileSync } from "node:fs";
const rows = readFileSync(process.argv[2], "utf8").trim().split("\n").map(l => l.split("\t"));
const scripts: Record<string,string> = {}; for (const r of rows) scripts[r[1]] = r[6] ?? "";
function published(script: string) {
  const out: {port:number, proto:string}[] = [];
  const re = /-p\s+(?:(\d+)(?:-(\d+))?:)?(\d+)(?:-(\d+))?(?:\/(tcp|udp))?/g; let m;
  while ((m = re.exec(script))) {
    const cs = Number(m[3]), ce = m[4] ? Number(m[4]) : cs; const proto = m[5] ?? "tcp";
    for (let p = cs; p <= ce; p++) out.push({ port: p, proto });
  }
  return out;
}
for (const fam of GAME_FAMILIES) {
  const s = scripts[fam]; if (!s) { console.log(`${fam}\tNO-TEMPLATE`); continue; }
  const pub = published(s);
  const has = (p: {port:number, protocol:string}) => pub.some(x => x.port === p.port && x.proto === p.protocol);
  const chk = GAME_PORT[fam], join = joinPortFor(fam), all = joinPortsFor(fam);
  const fwd = new Set(all.map(p => `${p.port}/${p.protocol}`));
  const notFwd = pub.filter(x => !fwd.has(`${x.port}/${x.proto}`)).map(x => `${x.port}/${x.proto}`);
  const img = (/\s([a-z0-9._\/-]+(?::[\w.-]+)?)(?:\s+-|\s*$)/i.exec(s.split("docker run")[1] ?? "") ? null : null);
  const imgM = /([a-z0-9._-]+\/[a-z0-9._\/-]+(?::[\w.-]+)?)(?=\s*(?:-c\s|$|\s+-autocreate))/i.exec(s.trim());
  console.log(`${fam}\tcheck=${chk.port}/${chk.protocol}:${has(chk)?"ok":"MISSING"}\tjoin=${join.port}/${join.protocol}:${has(join)?"ok":"MISSING"}\textra=${all.slice(1).map(p=>`${p.port}/${p.protocol}:${has(p)?"ok":"MISSING"}`).join(",")||"-"}\tpublished-not-forwarded(NAT)=${notFwd.join(",")||"-"}`);
}
EOF
cd $S && node --experimental-strip-types --no-warnings port-check.mts ostemplates.tsv | tee port-check.txt

